const MIN_SECRET_LENGTH = 32;
const MAX_TOKEN_LENGTH = 4096;
const NO_STORE_HEADERS = {
  "Cache-Control": "no-store, max-age=0",
  "Content-Type": "text/plain; charset=utf-8",
  "X-Content-Type-Options": "nosniff",
};

function isStrongSecret(value: string | undefined): value is string {
  return typeof value === "string" && value.length >= MIN_SECRET_LENGTH && !/\s/.test(value);
}

function authFailure(status: number, message: string): Response {
  return new Response(message, { status, headers: NO_STORE_HEADERS });
}

export async function authenticateCronRequest(request: Request): Promise<Response | null> {
  const currentSecret = process.env["LOVABLE_CRON_SECRET"];
  const configuredPreviousSecret = process.env["LOVABLE_CRON_SECRET_PREVIOUS"];
  const previousSecret =
    configuredPreviousSecret && configuredPreviousSecret.length > 0
      ? configuredPreviousSecret
      : undefined;

  // Fail closed on weak or malformed deployment configuration. This check is
  // deliberately separate from credential validation so misconfiguration
  // cannot silently disable authentication.
  if (
    !isStrongSecret(currentSecret) ||
    (previousSecret !== undefined && !isStrongSecret(previousSecret))
  ) {
    return authFailure(500, "Server configuration error");
  }

  // HTTP authentication schemes are case-insensitive. Do not accept commas,
  // embedded whitespace, empty tokens, or unbounded values.
  const match = /^Bearer ([^\s,]+)$/i.exec(request.headers.get("authorization") ?? "");
  const token = match?.[1];
  if (!token || token.length > MAX_TOKEN_LENGTH) {
    return authFailure(401, "Unauthorized");
  }

  const { createHash, timingSafeEqual } = await import("node:crypto");
  const digest = (value: string) => createHash("sha256").update(value, "utf8").digest();
  const providedDigest = digest(token);
  const currentMatches = timingSafeEqual(providedDigest, digest(currentSecret));

  // Keep the same number of digest comparisons with or without a rotation key.
  // A match against the fallback current digest is ignored when no previous
  // secret is configured.
  const previousMatchesDigest = timingSafeEqual(
    providedDigest,
    digest(previousSecret ?? currentSecret),
  );
  const previousMatches = previousSecret !== undefined && previousMatchesDigest;

  if (!currentMatches && !previousMatches) {
    return authFailure(401, "Unauthorized");
  }

  return null;
}
